function seg(key,opts){return '<div class="seg">'+opts.map(function(o){return '<button data-a="pset" data-key="'+key+'" data-val="'+o[0]+'" aria-selected="'+(String(PS[key])===String(o[0]))+'">'+o[1]+"</button>"}).join("")+"</div>"}
